css:
.fx-let{text-align:center;display:grid;gap:1em;justify-items:center;max-width:980px}
.fx-let h1{font-size:clamp(2.6em,7.5vw,5.6em);line-height:1.05;cursor:pointer}
.fx-let .w{display:inline-block;white-space:nowrap}
.fx-let .c{display:inline-block;opacity:0;transform:translateY(.7em) rotate(5deg);animation:fxlet calc(.75s/var(--speed)) cubic-bezier(.2,.8,.2,1) forwards;animation-delay:calc(var(--i)*38ms/var(--speed))}
.fx-let h1 em{font-style:italic;color:var(--accent)}
.fx-let small{opacity:.5;font-size:.85em}
@keyframes fxlet{to{opacity:1;transform:none}}
@media(prefers-reduced-motion:reduce){.fx-let .c{animation:none;opacity:1;transform:none}}
